#!/usr/bin/env node
/**
 * Downloads the map's static data artifacts into public/map/ so the app
 * serves them from its own origin:
 * - the Hong Kong vector tile archive (PMTiles) generated by the forked
 *   hk-pmtiles-generation workflow
 * - the protomaps label/POI sprite sheet (json + png, 1x/2x)
 * - the glyph ranges the basemap style actually requests (Noto Sans
 *   Regular/Medium/Italic; CJK renders locally via MapLibre's ideograph
 *   rasterizer and is never fetched)
 *
 * Third-party hosts get blocked or drop connections on some mobile networks;
 * same-origin never is. Runs as a prebuild/predev step:
 * - skips artifacts that already exist (set FORCE_MAP_TILE_FETCH=1 to force)
 * - verifies the PMTiles magic before writing
 * - hosts come from env overrides, so mirrors need no code change
 */
import { createHash } from 'node:crypto'
import { mkdirSync, existsSync, statSync } from 'node:fs'
import { open, rename, writeFile } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const TILES_URL =
  process.env.MAP_TILE_FETCH_URL ||
  'https://timothy0509.github.io/hk-pmtiles-generation/hong-kong.pmtiles'
const TILES_PATH = join(REPO_ROOT, 'public', 'map', 'hong-kong.pmtiles')

const SPRITE_BASE_URL =
  process.env.MAP_SPRITE_FETCH_URL || 'https://protomaps.github.io/basemaps-assets/sprites/v4/light'

// Glyph PBFs for the exact fontstacks the style requests. CJK codepoints
// render locally (MapLibre's ideograph rasterizer) and are never fetched,
// so only the small Latin/symbol ranges need mirroring.
const FONT_BASE_URL =
  process.env.MAP_FONT_FETCH_URL || 'https://protomaps.github.io/basemaps-assets/fonts'
const FONT_STACKS = ['Noto Sans Regular', 'Noto Sans Medium', 'Noto Sans Italic']
const FONT_RANGES = ['0-255', '8192-8447']

function log(msg) {
  console.log(`[fetch-map-data] ${msg}`)
}

function isForce() {
  return process.env.FORCE_MAP_TILE_FETCH === '1'
}

async function isPmtilesValid(path) {
  if (!existsSync(path) || statSync(path).size < 1_000_000) return false
  const handle = await open(path, 'r')
  try {
    const { buffer } = await handle.read(Buffer.alloc(8), 0, 8, 0)
    return buffer.toString('ascii', 0, 7) === 'PMTiles'
  } finally {
    await handle.close()
  }
}

async function fetchWithRetry(url, attempts = 3) {
  let lastError = null
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      const response = await fetch(url, { cache: 'no-store' })
      if (!response.ok) throw new Error(`${response.status} ${response.statusText}`)
      return Buffer.from(await response.arrayBuffer())
    } catch (err) {
      lastError = err
      log(`attempt ${attempt} failed for ${url}: ${err}`)
    }
  }
  throw lastError
}

async function writeAtomic(path, bytes) {
  mkdirSync(dirname(path), { recursive: true })
  const tempPath = `${path}.tmp`
  await writeFile(tempPath, bytes)
  await rename(tempPath, path)
}

async function fetchTiles() {
  if (!isForce() && (await isPmtilesValid(TILES_PATH))) {
    log('tile archive already present and valid, skipping')
    return
  }
  log(`downloading ${TILES_URL}`)
  let bytes = null
  try {
    bytes = await fetchWithRetry(TILES_URL)
  } catch {
    bytes = null
  }
  if (!bytes || bytes.length < 1_000_000 || bytes.toString('ascii', 0, 7) !== 'PMTiles') {
    // A tile-less map is a grey rectangle, not a graceful degradation — fail
    // loudly under CI (Vercel sets CI=true) instead of shipping it silently.
    // Locally this stays a warning so a flaky network never blocks dev.
    console.error(
      '[fetch-map-data] giving up: the map will lack tiles. Check network reachability of the tile archive host.'
    )
    if (process.env.CI === 'true') process.exitCode = 1
    return
  }
  await writeAtomic(TILES_PATH, bytes)
  const sha = createHash('sha256').update(bytes).digest('hex').slice(0, 12)
  log(`wrote ${TILES_PATH} (${(bytes.length / 1_048_576).toFixed(1)} MiB, sha256 ${sha})`)
}

async function fetchSprite() {
  const spriteDir = join(REPO_ROOT, 'public', 'map', 'sprite')
  // All four densities must exist: MapLibre appends @2x to the path stem on
  // high-DPI screens (the file the phone requests), and a missing density
  // surfaces as a 404 overlay that drops every icon.
  let missing = false
  for (const name of ['sprite.json', 'sprite.png', 'sprite@2x.json', 'sprite@2x.png']) {
    if (isForce() || !existsSync(join(spriteDir, name))) missing = true
  }
  if (!missing) {
    log('sprite already present, skipping')
    return
  }
  log(`downloading sprite sheets from ${SPRITE_BASE_URL}`)
  try {
    // The build-time mirror fetches upstream names (light.json/png/@2x)
    // but the style advertises /map/sprite/sprite{,@2x}.{json,png}, so copy
    // across during download. Both densities must exist: MapLibre appends
    // @2x to the path stem on high-DPI screens (the file the phone
    // requests), and a missing density surfaces as a 404 overlay that drops
    // every icon.
    for (const [upstream, local] of [
      ['light', 'sprite'],
      ['light@2x', 'sprite@2x'],
    ]) {
      for (const ext of ['.json', '.png']) {
        const bytes = await fetchWithRetry(`${SPRITE_BASE_URL}${upstream}${ext}`)
        await writeAtomic(join(spriteDir, `${local}${ext}`), bytes)
        log(`wrote /map/sprite/${local}${ext} (${bytes.length} bytes)`)
      }
    }
  } catch (err) {
    // Icons degrade to invisible pins; labels and shapes keep working.
    log(`sprite fetch failed (icons will be missing): ${err}`)
  }
}

async function fetchFonts() {
  const fontsDir = join(REPO_ROOT, 'public', 'map', 'fonts')
  let missing = false
  for (const stack of FONT_STACKS) {
    for (const range of FONT_RANGES) {
      if (isForce() || !existsSync(join(fontsDir, stack, `${range}.pbf`))) missing = true
    }
  }
  if (!missing) {
    log('fonts already present, skipping')
    return
  }
  log(`downloading glyph ranges from ${FONT_BASE_URL}`)
  try {
    for (const stack of FONT_STACKS) {
      for (const range of FONT_RANGES) {
        const bytes = await fetchWithRetry(
          `${FONT_BASE_URL}/${encodeURIComponent(stack)}/${range}.pbf`
        )
        await writeAtomic(join(fontsDir, stack, `${range}.pbf`), bytes)
        log(`wrote /map/fonts/${stack}/${range}.pbf (${bytes.length} bytes)`)
      }
    }
  } catch (err) {
    // Labels degrade to locally rasterized fallbacks; shapes keep working.
    log(`font fetch failed (labels will use fallback rendering): ${err}`)
  }
}

async function main() {
  await fetchTiles()
  await fetchSprite()
  await fetchFonts()
}

main().catch((err) => {
  console.error('[fetch-map-data] failed:', err)
  process.exitCode = 1
})
